(function(){
function Panzoom(el,opts={}){let state={x:0,y:0,scale:1};const min=opts.minScale??1,max=opts.maxScale??4;let down=false,sx=0,sy=0;
const apply=()=>{(opts.setTransform?opts.setTransform(el,state):el.style.transform=`translate(${state.x}px, ${state.y}px) scale(${state.scale})`)};
el.style.touchAction='none';
el.addEventListener('pointerdown',e=>{down=true;sx=e.clientX-state.x;sy=e.clientY-state.y;el.setPointerCapture(e.pointerId)});
el.addEventListener('pointermove',e=>{if(!down) return;state.x=e.clientX-sx;state.y=e.clientY-sy;apply();});
const up=()=>{down=false};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);
function zoomWithWheel(e){e.preventDefault();const delta=e.deltaY<0?1.08:0.92;state.scale=Math.min(max,Math.max(min,state.scale*delta));apply();}
apply();return {zoomWithWheel,reset(){state={x:0,y:0,scale:1};apply();},getScale(){return state.scale;}}}
window.Panzoom=Panzoom;
})();
